/* Costate feedback law (manuscript Eq. (9)) for the CCU firmware - portable C99, float.
 *
 *   u = argmin_{u in U} rho * P_fan * u^p_exp - u * B(x),
 *   B(x) = - sum_p lam_p^T M1_p x_p,   lam_p = Minv_T_p * w_p(x),
 *   w_p(x) = occ * W_p + M * 1[x_p > cb_p] / cb_p          (elementwise)
 *
 * x is the interval-averaged zone concentration (one value per node/zone and pollutant), so the gateway
 * must forward per-node readings rather than the per-pollutant maximum used by the relay firmware.
 * Parameters are generated by experiments/export_costate.py into costate_params.h.
 */
#ifndef COSTATE_LAW_H
#define COSTATE_LAW_H
#include <math.h>

#ifndef CS_NP
#define CS_NP 6
#endif
#ifndef CS_NZ
#define CS_NZ 3
#endif
#ifndef CS_NU
#define CS_NU 4
#endif

typedef struct {
    float Minv_T[CS_NP][CS_NZ][CS_NZ];  /* (-M_p(u_ref)^T)^{-1} */
    float M1[CS_NP][CS_NZ][CS_NZ];      /* purifier part of the generator */
    float W[CS_NP][CS_NZ];              /* index weights phi_p / g_p * psi_j */
    float cb[CS_NP];                    /* operating bounds */
    float M;                            /* soft-bound penalty */
    float rho;                          /* economic weight, (index h) per Wh */
    float p_fan, p_exp;                 /* fan power model */
    float duties[CS_NU];
} costate_params_t;

/* Returns the index of the selected duty. occ = 1 during (or within 30 min before) the shift. */
static inline int costate_duty(const costate_params_t *c, const float x[CS_NP][CS_NZ], float occ, float rho)
{
    float B = 0.0f, best = 1e30f;
    int p, i, j, u, iu = 0;
    for (p = 0; p < CS_NP; ++p) {
        float w[CS_NZ], lam[CS_NZ], m1x[CS_NZ];
        for (j = 0; j < CS_NZ; ++j)
            w[j] = occ * c->W[p][j] + (x[p][j] > c->cb[p] ? c->M / c->cb[p] : 0.0f);
        for (i = 0; i < CS_NZ; ++i) {
            float s = 0.0f, t = 0.0f;
            for (j = 0; j < CS_NZ; ++j) { s += c->Minv_T[p][i][j] * w[j]; t += c->M1[p][i][j] * x[p][j]; }
            lam[i] = s; m1x[i] = t;
        }
        for (i = 0; i < CS_NZ; ++i) B -= lam[i] * m1x[i];
    }
    for (u = 0; u < CS_NU; ++u) {
        float d = c->duties[u];
        float cost = rho * c->p_fan * powf(d, c->p_exp) - d * B;
        if (cost < best) { best = cost; iu = u; }
    }
    return iu;
}
#endif
